1	import { useCallback, useEffect, useRef, useState } from "react";
2	import { TFile } from "obsidian";
3	import {
4	  TLArrowBindingProps,
5	  TLShapeId,
6	  createShapeId,
7	  useEditor,
8	  useValue,
9	} from "tldraw";
10	import DiscourseGraphPlugin from "~/index";
11	import { getRelationTypeById } from "~/utils/typeUtils";
12	import { DiscourseNodeShape } from "~/components/canvas/shapes/DiscourseNodeShape";
13	import {
14	  DiscourseRelationShape,
15	  DiscourseRelationUtil,
16	} from "~/components/canvas/shapes/DiscourseRelationShape";
17	import {
18	  createOrUpdateArrowBinding,
19	  getArrowBindings,
20	} from "~/components/canvas/utils/relationUtils";
21	import { DEFAULT_TLDRAW_COLOR } from "~/utils/tldrawColors";
22	import { showToast } from "~/components/canvas/utils/toastUtils";
23	import {
24	  getDiscourseNodeAtPoint,
25	  getDiscourseNodeTypeId,
26	  hasValidRelationTypeForNodePair,
27	} from "~/components/canvas/utils/relationTypeUtils";
28	import { RelationTypeDropdown } from "./RelationTypeDropdown";
29	
30	type DragHandleOverlayProps = {
31	  plugin: DiscourseGraphPlugin;
32	  file: TFile;
33	};
34	
35	type HandlePosition = {
36	  x: number;
37	  y: number;
38	  anchor: { x: number; y: number };
39	};
40	
41	const HANDLE_RADIUS = 5;
42	const HANDLE_HIT_AREA = 12;
43	const HANDLE_PADDING = 8; // px offset in viewport space, outward from the node edge
44	
45	/** Page-space edge midpoints and their outward direction vectors. */
46	const getEdgeMidpoints = (bounds: {
47	  minX: number;
48	  minY: number;
49	  maxX: number;
50	  maxY: number;
51	}): (HandlePosition & { direction: { x: number; y: number } })[] => {
52	  return [
53	    // Top
54	    {
55	      x: (bounds.minX + bounds.maxX) / 2,
56	      y: bounds.minY,
57	      anchor: { x: 0.5, y: 0 },
58	      direction: { x: 0, y: -1 },
59	    },
60	    // Right
61	    {
62	      x: bounds.maxX,
63	      y: (bounds.minY + bounds.maxY) / 2,
64	      anchor: { x: 1, y: 0.5 },
65	      direction: { x: 1, y: 0 },
66	    },
67	    // Bottom
68	    {
69	      x: (bounds.minX + bounds.maxX) / 2,
70	      y: bounds.maxY,
71	      anchor: { x: 0.5, y: 1 },
72	      direction: { x: 0, y: 1 },
73	    },
74	    // Left
75	    {
76	      x: bounds.minX,
77	      y: (bounds.minY + bounds.maxY) / 2,
78	      anchor: { x: 0, y: 0.5 },
79	      direction: { x: -1, y: 0 },
80	    },
81	  ];
82	};
83	
84	export const DragHandleOverlay = ({ plugin, file }: DragHandleOverlayProps) => {
85	  const editor = useEditor();
86	  const [pendingArrowId, setPendingArrowId] = useState<TLShapeId | null>(null);
87	  const [isDragging, setIsDragging] = useState(false);
88	  const sourceNodeRef = useRef<DiscourseNodeShape | null>(null);
89	  const dragCleanupRef = useRef<(() => void) | null>(null);
90	
91	  // Clean up drag listeners on unmount
92	  useEffect(() => {
93	    return () => {
94	      dragCleanupRef.current?.();
95	    };
96	  }, []);
97	
98	  // Track the single selected discourse node — mirrors RelationsOverlay pattern
99	  const selectedNode = useValue<DiscourseNodeShape | null>(
100	    "dragHandleSelectedNode",
101	    () => {
102	      const shape = editor.getOnlySelectedShape();
103	      if (shape && shape.type === "discourse-node") {
104	        return shape as DiscourseNodeShape;
105	      }
106	      return null;
107	    },
108	    [editor],
109	  );
110	
111	  const handlePositions = useValue<
112	    { left: number; top: number; anchor: { x: number; y: number } }[] | null
113	  >(
114	    "dragHandlePositions",
115	    () => {
116	      if (!selectedNode || pendingArrowId || isDragging) return null;
117	      const bounds = editor.getShapePageBounds(selectedNode.id);
118	      if (!bounds) return null;
119	      const midpoints = getEdgeMidpoints(bounds);
120	      return midpoints.map((mp) => {
121	        const vp = editor.pageToViewport({ x: mp.x, y: mp.y });
122	        return {
123	          left: vp.x + mp.direction.x * HANDLE_PADDING,
124	          top: vp.y + mp.direction.y * HANDLE_PADDING,
125	          anchor: mp.anchor,
126	        };
127	      });
128	    },
129	    [editor, selectedNode?.id, pendingArrowId, isDragging],
130	  );
131	
132	  const cleanupArrow = useCallback(
133	    (arrowId: TLShapeId) => {
134	      if (editor.getShape(arrowId)) {
135	        editor.deleteShapes([arrowId]);
136	      }
137	    },
138	    [editor],
139	  );
140	
141	  const handlePointerDown = useCallback(
142	    (e: React.PointerEvent, anchor: { x: number; y: number }) => {
143	      if (!selectedNode) return;
144	      e.preventDefault();
145	      e.stopPropagation();
146	
147	      setIsDragging(true);
148	      sourceNodeRef.current = selectedNode;
149	
150	      const arrowId = createShapeId();
151	
152	      // Get the source node's page bounds for start position
153	      const sourceBounds = editor.getShapePageBounds(selectedNode.id);
154	      if (!sourceBounds) {
155	        setIsDragging(false);
156	        return;
157	      }
158	
159	      const startX = sourceBounds.minX + anchor.x * sourceBounds.width;
160	      const startY = sourceBounds.minY + anchor.y * sourceBounds.height;
161	
162	      // Create the arrow shape at the source node's position
163	      editor.createShape<DiscourseRelationShape>({
164	        id: arrowId,
165	        type: "discourse-relation",
166	        x: startX,
167	        y: startY,
168	        props: {
169	          color: DEFAULT_TLDRAW_COLOR,
170	          relationTypeId: "",
171	          text: "",
172	          dash: "draw",
173	          size: "m",
174	          fill: "none",
175	          labelColor: "black",
176	          bend: 0,
177	          start: { x: 0, y: 0 },
178	          end: { x: 0, y: 0 },
179	          arrowheadStart: "none",
180	          arrowheadEnd: "arrow",
181	          labelPosition: 0.5,
182	          font: "draw",
183	          scale: 1,
184	          kind: "arc",
185	          elbowMidPoint: 0,
186	        },
187	      });
188	
189	      const createdShape = editor.getShape<DiscourseRelationShape>(arrowId);
190	      if (!createdShape) {
191	        setIsDragging(false);
192	        return;
193	      }
194	
195	      // Bind the start handle to the source node
196	      createOrUpdateArrowBinding(editor, createdShape, selectedNode.id, {
197	        terminal: "start",
198	        normalizedAnchor: anchor,
199	        isPrecise: false,
200	        isExact: false,
201	        snap: "none",
202	      });
203	
204	      // Select the arrow and start dragging the end handle
205	      editor.select(arrowId);
206	
207	      // Use tldraw's built-in handle dragging by setting the tool state
208	      // We need to track the pointer to update the end handle
209	      const containerEl = editor.getContainer();
210	      const onPointerMove = (moveEvent: PointerEvent) => {
211	        const point = editor.screenToPage({
212	          x: moveEvent.clientX,
213	          y: moveEvent.clientY,
214	        });
215	
216	        // Update the arrow's end position
217	        const currentShape = editor.getShape<DiscourseRelationShape>(arrowId);
218	        if (!currentShape) return;
219	
220	        const dx = point.x - currentShape.x;
221	        const dy = point.y - currentShape.y;
222	
223	        // Check for a target shape under the cursor
224	        const target = getDiscourseNodeAtPoint(editor, point, selectedNode.id);
225	
226	        if (target) {
227	          // Bind end to target
228	          createOrUpdateArrowBinding(editor, currentShape, target.id, {
229	            terminal: "end",
230	            normalizedAnchor: { x: 0.5, y: 0.5 },
231	            isPrecise: false,
232	            isExact: false,
233	            snap: "none",
234	          });
235	          editor.setHintingShapes([target.id]);
236	        } else {
237	          // Update free end position
238	          // Remove any existing end binding
239	          const bindings = getArrowBindings(editor, currentShape);
240	          if (bindings.end) {
241	            editor.deleteBindings(
242	              editor
243	                .getBindingsFromShape(currentShape.id, "discourse-relation")
244	                .filter(
245	                  (b) => (b.props as TLArrowBindingProps).terminal === "end",
246	                ),
247	            );
248	          }
249	          editor.updateShapes([
250	            {
251	              id: arrowId,
252	              type: "discourse-relation",
253	              props: { end: { x: dx, y: dy } },
254	            },
255	          ]);
256	          editor.setHintingShapes([]);
257	        }
258	      };
259	
260	      const onPointerUp = () => {
261	        containerEl.removeEventListener("pointermove", onPointerMove);
262	        containerEl.removeEventListener("pointerup", onPointerUp);
263	        dragCleanupRef.current = null;
264	        editor.setHintingShapes([]);
265	        setIsDragging(false);
266	
267	        const finalShape = editor.getShape<DiscourseRelationShape>(arrowId);
268	        if (!finalShape) return;
269	
270	        const bindings = getArrowBindings(editor, finalShape);
271	
272	        // Validate: both ends bound to different discourse nodes
273	        if (
274	          bindings.start &&
275	          bindings.end &&
276	          bindings.start.toId !== bindings.end.toId
277	        ) {
278	          const endTarget = editor.getShape(bindings.end.toId);
279	          if (endTarget && endTarget.type === "discourse-node") {
280	            // Check if any relation types are valid for this node pair
281	            const startNodeTypeId = getDiscourseNodeTypeId(
282	              editor.getShape(bindings.start.toId),
283	            );
284	            const endNodeTypeId = getDiscourseNodeTypeId(endTarget);
285	
286	            const hasValidRelationType =
287	              startNodeTypeId &&
288	              endNodeTypeId &&
289	              hasValidRelationTypeForNodePair({
290	                settings: plugin.settings,
291	                sourceNodeTypeId: startNodeTypeId,
292	                targetNodeTypeId: endNodeTypeId,
293	              });
294	
295	            if (!hasValidRelationType) {
296	              cleanupArrow(arrowId);
297	              showToast({
298	                severity: "warning",
299	                title: "Relation",
300	                description:
301	                  "No relation types are defined between these node types",
302	                targetCanvasId: file.path,
303	              });
304	              if (sourceNodeRef.current) {
305	                editor.select(sourceNodeRef.current.id);
306	              }
307	              sourceNodeRef.current = null;
308	              return;
309	            }
310	
311	            // Success - show dropdown to pick relation type
312	            setPendingArrowId(arrowId);
313	            editor.select(arrowId);
314	            return;
315	          }
316	        }
317	
318	        // Failure - clean up the arrow and show notice
319	        cleanupArrow(arrowId);
320	        showToast({
